const request = $json.body ?? $json;
const required = ['repo', 'title', 'summary', 'type', 'source'];
const missing = required.filter((key) => request[key] === undefined || request[key] === null || request[key] === '');
if (missing.length) throw new Error(`Missing required fields: ${missing.join(', ')}`);
if (request.repo !== 'ElishaSamPeterPrabhu/modus-wc-2.0') throw new Error('Pilot service only accepts the private pilot repository.');
if (request.autoApprove === true || request.auto_approve === true) throw new Error('Pilot issue service never auto-approves.');
const source = request.source || {};
const idempotencyKey = request.idempotencyKey || request.idempotency_key;
if (!idempotencyKey) throw new Error('idempotencyKey is required.');
const staticData = $getWorkflowStaticData('global');
staticData.requests = staticData.requests || {};
const prior = staticData.requests[idempotencyKey];
if (prior) return [{ json: { route: 'existing', response: prior } }];
const normalized = {
  repo: request.repo,
  title: String(request.title).slice(0, 200),
  summary: String(request.summary).slice(0, 12000),
  type: request.type,
  components: Array.isArray(request.components) ? request.components : [],
  labels: Array.isArray(request.labels) ? request.labels : ['needs-scaffolding'],
  source,
  rawConversation: Array.isArray(request.rawConversation) ? request.rawConversation.slice(-100) : [],
  contextEvidence: Array.isArray(request.contextEvidence) ? request.contextEvidence.slice(-100) : [],
  additionalContext: request.additionalContext || request.additional_context || {},
  idempotencyKey,
  autoApprove: false,
};
staticData.requests[idempotencyKey] = { status: 'processing', idempotencyKey, startedAt: Date.now() };
return [{ json: { route: 'create', normalized } }];

const result = $json;
const source = $('Validate and Deduplicate').item.json.normalized;
const response = { ok: true, status: result.issueUrl || result.url ? 'created' : 'pending', issueUrl: result.issueUrl || result.url || result.issue?.html_url || null, idempotencyKey: source.idempotencyKey, scaffolding: result.status || 'pending' };
const staticData = $getWorkflowStaticData('global');
staticData.requests[source.idempotencyKey] = response;
return [{ json: { response } }];
